// Server-side conversion submission to xTracky (https://docs.xtracky.com/api-reference/enviar-conversao).
// POST https://api.xtracky.com/api/integrations/api — no API key; the sale is tied to a lead
// through `utm_source`, which must be the LeadId generated by the xTracky V2 script
// (e.g. "TT-1763007625226-yn4xita3qylwh"). A sale without a LeadId is treated as organic.

const XTRACKY_API = "https://api.xtracky.com/api/integrations/api";

export type XtrackyConversion = {
  orderId: string;
  amountInCents: number;
  currency: string;
  leadId: string;
  status?: "paid" | "waiting_payment" | "initiate_checkout" | "failed" | "refunded";
  name?: string;
  email?: string;
  phone?: string;
};

export async function sendXtrackyConversion(conversion: XtrackyConversion) {
  const response = await fetch(XTRACKY_API, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      orderId: conversion.orderId,
      amount: conversion.amountInCents,
      status: conversion.status ?? "paid",
      platform: "Digistore24",
      utm_source: conversion.leadId,
      currency: conversion.currency,
      ...(conversion.name ? { leadName: conversion.name } : {}),
      ...(conversion.email ? { leadEmail: conversion.email } : {}),
      ...(conversion.phone ? { leadPhone: conversion.phone } : {}),
    }),
  });

  const result = (await response.json().catch(() => ({}))) as {
    success?: boolean;
    error?: string;
    message?: string;
    dedupped?: boolean;
  };

  // 409 = duplicate (already processed), which is fine for a retried postback.
  const accepted = response.ok ? result.success !== false : response.status === 409;
  if (!accepted) {
    console.error("[xTracky] Conversion rejected", {
      status: response.status,
      error: result.error ?? "",
      message: result.message ?? "",
      order_id: conversion.orderId,
    });
  }
  return accepted;
}
